import type { Metadata } from "next";
import { LegalDraft, type DraftSection } from "@/components/LegalDraft";

export const metadata: Metadata = { title: "Account Deletion — Draft", robots: { index: false, follow: false } };

const sections: DraftSection[] = [
  { id: "in-app", title: "Delete Your Account in the App", body: <><p>You can request permanent deletion of your Cubyfit account and supported associated personal records. This action cannot be undone.</p><ol><li>Sign in to Cubyfit.</li><li>Go to <strong>Account → Data &amp; Privacy → Delete Account</strong>.</li><li>Read the warning and enter <code>DELETE-ACCOUNT</code>.</li><li>Complete Clerk identity reverification with the required email code.</li><li>Submit the deletion request.</li></ol><p>The app displays available progress information while the deletion service works. Completion may take time or require retries.</p></> },
  { id: "outside", title: "Cannot Access Your Account?", body: <><p>An outside-app request channel is being established. <strong>[VERIFIED ACCOUNT DELETION EMAIL PENDING]</strong> must be a monitored, working address before this page can be published as an external request pathway.</p><p>When available, email that address with the subject <strong>Cubyfit Account Deletion Request</strong>, identify the email associated with your Cubyfit account, and clearly request permanent deletion. We may require secure proof of ownership. Never email a password, authentication code or session token. You should not need to reinstall the app to initiate an outside-app request.</p><p><strong>Before publication:</strong> Assign an owner, implement a secure authorized manual workflow, and verify the mailbox and a seven-calendar-day acknowledgement target. No response time is promised by this unpublished draft.</p></> },
  { id: "deleted", title: "What the Process Deletes", body: <><p>The verified deletion job removes supported account-owned active Convex records: profile; habits and historical completions; missions and completions; custom exercises; routines; workouts, nested exercises and sets; weights; measurements; rest days; favorites; preferences; and synchronization records and operations. These cover supported cloud-backed fitness, nutrition and account-linked progress records.</p><p>The job then requests deletion of the matching RevenueCat customer and Clerk identity. If a customer has another nonanonymous alias, processing pauses for review instead of deleting an ambiguous customer. The device that observes completion removes the matching account-specific SQLite file and reminders.</p><p>Cubyfit does not intend to retain identifiable fitness statistics solely for business analytics after account deletion. No separate account-linked business-analytics warehouse was identified in the reviewed source.</p></> },
  { id: "remaining", title: "What May Remain", body: <><ul><li>A limited technical deletion-status record for about 30 days after completion; incomplete jobs remain for retries and review.</li><li>Account data on disconnected devices until they reconnect and process completion. If the status record has expired by then, manual app-data clearing may be needed.</li><li>Operating-system and provider backups under separate schedules.</li><li>Store billing and transaction records, and provider-held security, diagnostic, advertising or infrastructure records under their applicable policies and obligations.</li><li>Guest data and shared downloaded catalog files, which are separate from authenticated account records.</li></ul><p>The current job has no direct purge for Sentry events, AdMob records, Cloudflare gateway state or app-store transactions. We cannot promise immediate erasure from every system.</p></> },
  { id: "subscription", title: "Cancel Your Subscription Separately", body: <p>Account deletion does not automatically cancel billing. To stop future renewals, manage the subscription with <a href="https://play.google.com/store/account/subscriptions">Google Play</a> or <a href="https://apps.apple.com/account/subscriptions">Apple</a>.</p> },
  { id: "help", title: "Need Help?", body: <p>Support: <strong>[VERIFIED SUPPORT EMAIL PENDING]</strong>. See the <a href="/privacy">Privacy Policy</a> and <a href="/terms">Terms of Use</a> drafts for more information. Cubyfit is developed by Mohamed Radouan, Marouan Younsi and Mouad Mezian in Casablanca, Morocco.</p> },
];

export default function DeleteAccountPage() {
  return <LegalDraft title="Delete Your Cubyfit Account" description="Your account. Your data. Your choice." sections={sections} note="This draft cannot yet accept an outside-app deletion request. A monitored mailbox and verified manual process are required before publication or use as the Play Console deletion URL." />;
}
